def namespace_exists(rel: str) -> bool:
    bp = SOURCE / rel / "Android.bp"
    if not bp.is_file():
        return False
    return "soong_namespace" in bp.read_text()[:4096]


def filter_nubia_vendor_imports() -> None:
    """Drop Lineage-only namespace imports from extract-utils Android.bp.

    Missing paths (hardware/qcom-caf/wlan, vendor/qcom/opensource/display, …)
    fail bootstrap. Those modules live in CLO at hardware/qcom/wlan or in the
