#!/usr/bin/env python3
"""Disable make-side ELF DT_NEEDED checks on nubia vendor prebuilts.

Soong analysis accepts namespaced deps (libgralloc.qti in
hardware/qcom-caf/sm8650/display/gralloc). The hybrid make check_elf_file
allowlist only sees root-namespace .so paths, so blobs fail with
DT_NEEDED libgralloc.qti.so is not specified in shared_libs even when
Android.bp already lists it.

Do not overlay whole vendor/nubia trees (they come from local_manifest).

Idempotent. SOURCE_DIR defaults to repo source/.
"""
from __future__ import annotations

import os
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = Path(os.environ.get("SOURCE_DIR", ROOT / "source"))
MARKER = "// AOSPA cerro: make check_elf cannot see namespaced CAF deps"
PREBUILT_TYPES = {
    "cc_prebuilt_library_shared",
    "cc_prebuilt_library_static",
    "cc_prebuilt_binary",
    "cc_prebuilt_object",
}
BPS = (
    SOURCE / "vendor/nubia/sm8650-common/Android.bp",
    SOURCE / "vendor/nubia/cerro/Android.bp",
)
NAME_RE = re.compile(r'(name: "[^"]+",\n)')


def split_top_level_blocks(text: str) -> list[str]:
    chunks: list[str] = []
    i = 0
    n = len(text)
    while i < n:
        while i < n and text[i] in " \t\r\n":
            i += 1
        if i >= n:
            break
        start = i
        if text.startswith("//", i):
            nl = text.find("\n", i)
            i = n if nl < 0 else nl + 1
            chunks.append(text[start:i])
            continue
        if text.startswith("/*", i):
            end = text.find("*/", i + 2)
            i = n if end < 0 else end + 2
            if i < n and text[i] == "\n":
                i += 1
            chunks.append(text[start:i])
            continue
        brace = text.find("{", i)
        if brace < 0:
            chunks.append(text[i:])
            break
        depth = 0
        j = brace
        while j < n:
            if text[j] == "{":
                depth += 1
            elif text[j] == "}":
                depth -= 1
                if depth == 0:
                    j += 1
                    break
            j += 1
        if j < n and text[j] == "\n":
            j += 1
        chunks.append(text[start:j])
        i = j
    return chunks


def module_type(block: str) -> str | None:
    stripped = block.lstrip()
    if stripped.startswith("//") or stripped.startswith("/*"):
        return None
    brace = stripped.find("{")
    if brace < 0:
        return None
    return stripped[:brace].strip()


def patch_block(block: str) -> str:
    if module_type(block) not in PREBUILT_TYPES:
        return block
    if MARKER in block or "check_elf_files:" in block:
        return block
    m = NAME_RE.search(block)
    if not m:
        return block
    indent = "    "
    return (
        block[: m.end()]
        + f"{indent}{MARKER}\n{indent}check_elf_files: false,\n"
        + block[m.end() :]
    )


def patch_file(path: Path) -> None:
    if not path.is_file():
        print(f"[nubia-elf] skip missing {path}")
        return
    text = path.read_text()
    leading = text[: len(text) - len(text.lstrip(" \t\r\n"))]
    blocks = split_top_level_blocks(text)
    patched = 0
    out = [leading] if leading else []
    for b in blocks:
        nb = patch_block(b)
        if nb != b:
            patched += 1
        out.append(nb)
    new = "".join(out)
    if not new.endswith("\n"):
        new += "\n"
    if patched == 0:
        print(f"[nubia-elf] {path.relative_to(SOURCE)} already patched or no prebuilts")
        return
    path.write_text(new)
    print(f"[nubia-elf] check_elf_files: false on {patched} modules in {path.relative_to(SOURCE)}")


def main() -> None:
    for bp in BPS:
        patch_file(bp)


if __name__ == "__main__":
    main()

